    "yasaStory": "1932년 1월 8일 사건: 이봉창 의사, 히로히토 일본 천황을 암살하려는 도쿄 사쿠라다몬 의거 발생.\n\n이봉창(李奉昌, 1900년 8월 10일 ~ 1932년 10월 10일)은 일제강점기의 상인, 독립운동가이다. 본관은 전주(全州)다. 일본으로 건너가 상인 등으로 활동하다가 대한민국 임시정부가 있는 중화민국 장쑤성 상하이로 건너가 한인애국단 단원이 되었다. 경성부의 중류층 가정에서 태어나 가정 형편으로 중학교에 진학하지 못했고 상점 점원, 철도청 견습생으로 일했고, 일본으로 건너가 상점 점원과 막노동 등에 종사하였다. 1918년 철도국의 견습사원이 되었으나 1년 후 조선인보다 늦게 입사한 일본인들에게 혜택을 주는 것에 분개하여 철도국을 그만두었고, 1928년에는 히로히토 천황의 즉위식에 구경하러 갔다가, 한글과 한문으로 된 편지를 소지하고 있었다는 이유로 체포되어 11일간 수감되었다. 조선인과 일본인을 차별하던 조선총독부의 정책에 불만을 품고 일본 정부에 항거하게 되었다. 1931년 중국으로 건너가 상하이 한인거류민단을 통해 김구를 찾아갔다. 능행에 오르던 천황을 눈앞에서 본 것을 밝히고..."
