    "yasaStory": "1927년 2월 8일 사건: 조선어 연구회가 기관지 을 창간하다.\n\n한글학회(한글學會, 영어: Korean Language Society)는 한글과 한국어를 연구하는 민간학술단체이다. 1908년에 ‘국어연구학회’라는 이름으로 창립되었으며, 여러차례 학회 명칭이 변경되었으나 1949년에 이르러 ‘한글학회’라는 이름을 가지게 되었다. 1907년에 설치되었던 '국문연구소'를 계승하며 우리말과 글의 연구.통일.발전을 목적으로 하고 있다. 한글학회는 1926년 11월 4일에 한글날(가갸날)을, 1933년에 한글맞춤법통일안을 제정하고, 한글을 보급하고자 노력했다. 해방 후, 학회는 한글전용을 주장해 국한문혼용을 한글전용으로 쓰는 것을 장려했다."
