    "yasaStory": "1922년 2월 28일 사건: 이집트가 영국으로부터 독립.\n\n이집트 아랍 공화국(아랍어: جُمْهُورِيَّة مِصْر اَلْعَرَبِيَّة 줌후리야트 미스르 알아라비야[*], 이집트 아랍어: جُمْهُورِيَّة مَصْر العَرَبِيَّة 굼후리야트 마스르 알아라비야, 듣기 ) 또는 이집트(아랍어: مِصْر 미스르[*], 이집트 아랍어: مَصْر 마스르, 콥트어: Ⲭⲏⲙⲓ 키미, 영어: Egypt, 문화어: 에짚트)는 북아프리카와 서아시아의 시나이반도에 걸쳐 있는 국가이다. 영토 면적은 100만 1,450 km2 수도는 카이로이다. 이집트는 그 어떠한 국가들보다 유구한 역사를 지니고 있는 국가들 중 하나이다. 약 5,000여 년 전부터 나일강가에서 문명이 태동하기 시작하였고, 기원전 30세기에 이르자 고대 이집트 문명은 문자, 농업, 도시화, 종교, 정부 등 모든 분야에서 동시대 타 지역에 비하여 압도적인 발전을 이룩하며 풍요로운 시대를 이루었다. 이 시기에 이집트에 기자의 피라미드와 대스핑크스가 세워졌으며, 멤피스..."
