    "yasaStory": "1939년 3월 3일 사건: 모한다스 간디가 인도에 대한 폭압 통치에 항의하는 단식을 시작하다.\n\n모한다스 카람찬드 간디(구자라트어: મોહનદાસ કરમચંદ ગાંધી, 힌디어: मोहनदास करमचन्द गांधी, 영어: Mohandas Karamchand Gandhi, 1869년 10월 2일 ~ 1948년 1월 30일)는 인도의 정신적·정치적 지도자로, 마하트마 간디(Mahatma Gandhi)라는 이름으로 널리 알려져 있는데 '마하트마'는 위대한 영혼이라는 뜻으로 인도의 시인인 타고르가 지어준 이름이다. 영국 유학을 다녀왔으며, 인도의 영국 식민지 기간(1859~1948) 중 대부분을 영국으로부터의 인도 독립 운동을 지도하였다. 인도 분할에 대한 반대를 하다가 인도의 분할이 일어나자, 종교 폭력에 대한 반대를 하다가 피살되었다. 1890년 영국 런던 대학교 법학과를 중퇴한 그는 이후 1916년 영국 런던 대학교 법학과에서 명예 학사 학위를 받았다. 영국의 제국주의에 맞서 반영 인도 독립운동과 무료 변호, 사티아그라하 등 무저항 비폭력 운동을 전개해 나갔다. 인도의 작은..."
