    "yasaStory": "1924년 3월 6일 사건: 일제강점기 속리산 법주사의 여승 변사사건이 발생, 충청북도지사 박중양과 연루된 것으로 밝혀져 화제가 되다.\n\n일제강점기(한국 한자: 日帝強占期, 일본어: 日本統治時代の朝鮮)는 한반도가 일제의 통치 하에 있었던 기간을 가리킨다. 일제강점기는 한국사에서 한국의 근현대사를 시대별로 나누었을 때 약 34년 11개월 16일(12,770일) 동안 이어진다. 1910년 한일병합 이후 통감 및 총독이 조선총독부를 통해 천황의 명을 받아 통치하는 형식으로 식민지배가 이루어졌으며, 한반도의 정치 및 외교 권한 또한 일본 제국에 있었다."
