    "officialRecord": "인도, 영국에 대한 저항 운동으로 소금 사티아그라하 감행.",
    "yasaStory": "1930년 3월 12일 사건: 인도, 영국에 대한 저항 운동으로 소금 사티아그라하 감행.\n\n인도 공화국(印度共和國, 힌디어: भारत गणराज्य 바라트 간라즈여, 영어: Republic of India 리퍼블릭 오브 인디아[*]), 약칭 인도(印度, 영어: India 인디아[*])는 남아시아에 있는 나라로, 인도 아대륙의 거의 대부분을 차지하고 있다. 인구는 2023년 이래로 세계에서 가장 많으며 국토 면적은 세계에서 일곱 번째로 넓다. 서쪽으로는 파키스탄, 동쪽으로는 미얀마와 방글라데시, 남동쪽에는 벵골만, 남서쪽으로는 아라비아해, 남쪽으로는 인도양과 맞닿아 그 주변으로 스리랑카, 몰디브가 있으며, 북쪽으로는 네팔, 부탄, 중국과도 맞닿아 있다. 안다만 니코바르 제도의 해상 경계는 태국, 인도네시아와 접해 있다. 수도는 뉴델리이다. 주요 도시로는 뭄바이, 첸나이, 벵갈루루, 하이데라바드, 콜카타 등이 있다. 고대 인더스 문명의 발상지이자 역사적인 무역로였으며 거대한 제국이 있었던 인도 아대륙은 오랫동안 그 지정학적 지위와 경제·문화적 가치를 인정 받아왔다. 인도는 4개의..."
