    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%96%91%EA%B8%B0%ED%83%81",
    "officialRecord": "독립 운동가 정이형, 양기탁 등이 만주 지린성에서 독립 운동단체 고려혁명당이 조직됐다.",
    "yasaStory": "1926년 4월 5일 사건: 독립 운동가 정이형, 양기탁 등이 만주 지린성에서 독립 운동단체 고려혁명당이 조직됐다.\n\n양기탁(梁起鐸, 문화어: 량기탁, 1871년 4월 2일~1938년 4월 19일)은 한국의 언론인, 독립 운동가이다. 아명(兒名)은 의종(宜鍾), 자(字)는 자명(子明), 만초(萬初)이다. 호(號)는 우강(雩岡), 운강(雲崗). 본관은 남원 양씨(梁氏) 병부공파(대종중) 26세이며 좨주공파(종중) 16대손이다."
