    "yasaStory": "1906년 4월 10일 사건: 고다마 겐타로 총독이 대만총독에서 물러났다.\n\n고다마 겐타로(일본어: 児玉 源太郎, 1852년 4월 14일(가에이 5년 2월 25일) ~ 1906년(메이지 39년) 7월 23일)는 일본 제국의 육군 군인이며 화족이다. 러일 전쟁 당시에 만주군 총참모장으로 참전하여 승리에 공헌한 명장으로 알려져 있다. 대만 총독, 육군대신, 내무대신, 문부대신, 육군참모총장 등을 역임하였고, 육군대장 정2위 훈1등 자작이다."
