    "officialRecord": "중화민국 상하이에서 대한민국 임시정부 수립.",
    "yasaStory": "1919년 4월 11일 사건: 중화민국 상하이에서 대한민국 임시정부 수립.\n\n중화민국(중국어 정체자: 中華民國, 병음: Zhōnghuá Mínguó, 주음 부호: ㄓㄨㄥ ㄏㄨㄚˊ ㄇㄧㄣˊ ㄍㄨㄛˊ 중화민궈[*], 영어: Republic of China, ROC)은 동아시아에 위치한 국가로, 실질적으로 168개의 섬들로 이루어져 있다. 현재는 중화민국 대신 국내외에서 영토 중 가장 큰 섬의 이름인 타이완(대만, 중국어 정체자: 臺灣/台灣, 궈위 발음: [tʰäɪ˧˥ ʋän˦])이라는 명칭을 주로 사용하지만 사실상 “대만”이라는 이름의 국가는 존재하지 않는다. 국제 기구나 스포츠 경기 대회에서는 차이니스 타이베이라는 명칭으로 참여하는 경우가 많다. 유엔의 정회원이 아니며 수교국이 12개국에 불과하다. 이웃 국가와 지역은 북서쪽의 중국 대륙과 동북쪽의 일본, 남쪽의 필리핀이 있다. 대만의 면적은 35,808㎢로 경상도 면적과 비슷하며 산맥 지형이 섬의 동쪽 3분의 2 정도를 차지하고, 서부에 펼쳐쳐 있는 평원 지형에 인구가 집중되어 있다. 인구는 2,370만 명으로..."
