    "officialRecord": "서울에서 한성임시정부 수립.",
    "yasaStory": "1919년 4월 23일 사건: 서울에서 한성임시정부 수립.\n\n서울특별시(-特別市)는 대한민국의 수도이자 특별시이다. 황해에서 약 60 km 떨어진 한강 연안에 자리 잡고 있으며, 경기도·인천광역시와 함께 수도권을 이룬다. 면적은 605.25 km2로 국토의 0.61%에 지나지 않지만, 2025년 인구총조사 기준 인구는 931만 5,066명으로 경기도 다음으로 많아 전국 인구의 18.0%를 차지한다. 인구는 1992년 1,097만 명으로 가장 많았다가 교외화와 출산율 저하로 줄어들고 있다. 시역은 한강을 사이에 두고 강북과 강남으로 나뉘며, 행정 구역은 25개 자치구와 427개 행정동으로 이루어져 있다. 헌법재판소는 2004년 서울이 수도라는 것을 관습헌법으로 확립된 사항으로 보았다. 서울 지역에는 신석기 시대부터 사람이 살았으며, 백제가 기원전 18년부터 475년까지 이곳에 도읍을 두었다. 고려 때 남경이 설치되었고, 1394년 조선이 한양으로 도읍을 옮긴 뒤 조선과 대한제국의 수도였다. 일제강점기에는 경성부로 개편되어 조선총독부 통치의 중심이..."
