    "yasaStory": "1929년 5월 5일 사건: 일제강점기, 조선비행학교가 개교하다.\n\n대한항공(大韓航空, 영어: Korean Airlines Co., Ltd., KAL)은 대한민국 국적의 항공사로 한진그룹의 계열사이며, 항공 동맹체인 스카이팀의 창립 항공사다. 본사는 서울특별시 강서구 하늘길 260에 있으며 인천국제공항, 김해국제공항과 김포국제공항을 허브 공항으로 두고 있다."
