    "yasaStory": "1913년 5월 13일 사건: 한국의 독립운동: 안창호·송종우 등이 미국 샌프란시스코에서 흥사단을 조직하다.\n\n한국의 독립운동은 한국이 일제를 주축으로 한 제국주의 국가들의 침략 및 지배로부터 대항한 일련의 운동이다. 이러한 독립운동은 19세기 중엽부터 시작해 1945년 8월 15일에 일제가 항복을 선언할 때까지 진행되었다."
