    "source": "위키백과 · 일제강점기",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%9D%BC%EC%A0%9C%EA%B0%95%EC%A0%90%EA%B8%B0",
    "officialRecord": "일제강점기 경상남도 진주에서 강상호 등이 백정 해방 목적으로 형평사 연맹 총본부 조직하다.",
    "yasaStory": "1923년 5월 13일 사건: 일제강점기 경상남도 진주에서 강상호 등이 백정 해방 목적으로 형평사 연맹 총본부 조직하다.\n\n일제강점기(한국 한자: 日帝強占期, 일본어: 日本統治時代の朝鮮)는 한반도가 일제의 통치 하에 있었던 기간을 가리킨다. 일제강점기는 한국사에서 한국의 근현대사를 시대별로 나누었을 때 약 34년 11개월 16일(12,770일) 동안 이어진다. 1910년 한일병합 이후 통감 및 총독이 조선총독부를 통해 천황의 명을 받아 통치하는 형식으로 식민지배가 이루어졌으며, 한반도의 정치 및 외교 권한 또한 일본 제국에 있었다."
