    "officialRecord": "한용운, 조선불교유신론 발간하다.",
    "yasaStory": "1913년 5월 25일 사건: 한용운, 조선불교유신론 발간하다.\n\n한용운(韓龍雲, 1879년 8월 29일 (음력 7월 12일) ~ 1944년 6월 29일)은 일제강점기의 시인, 승려, 독립운동가이다. 본관은 청주. 호는 만해(萬海)이다. 불교를 통한 언론, 교육 활동을 하였다. 종래의 무능한 불교를 개혁하고 불교의 현실참여를 주장하였으며, 그것에 대한 대안점으로 불교사회개혁론을 주장했다. 3·1 만세 운동 당시 민족대표 33인의 한사람이며 광복 1년을 앞둔 1944년 6월 29일에 중풍병사(입적)하였다. 독립선언서의 \"공약 3장\"을 추가보완하였고 옥중에서 '조선 독립의 서'(朝鮮獨立之書)를 지어 독립과 자유를 주장하였다. 1910년 일본이 주장하는 한일불교동맹을 반대철폐하고 이회영, 박은식, 김동삼 등의 독립지사(志士)들을 만나 독립운동을 협의하였다. 1918년 11월부터는 불교 최초의 잡지인 《유심》을 발행하였고 1919년 3.1 만세 운동 당시 독립선언을 하여 체포당한 뒤 3년간 서대문 형무소에서 복역하다 풀려났다. 1920년대에는 대처승 운동을..."
