    "officialRecord": "대한제국, 마산선 삼랑진 - 마산포 간 철도가 개통되어 직통 열차가 운행을 개시하다.",
    "yasaStory": "1905년 5월 26일 사건: 대한제국, 마산선 삼랑진 - 마산포 간 철도가 개통되어 직통 열차가 운행을 개시하다.\n\n대한국(大韓國), 약칭 대한제국(大韓帝國) 또는 한국(韓國)은 1897년 10월 12일부터 1910년 8월 29일까지 존재했던 황제국으로, 조선을 계승한 국가이자 한반도의 마지막 전제군주국이었다. 대한제국이 존재했던 기간과 그 주변 기간을 합쳐 구한말(舊韓末)이라고 부르기도 한다. 대한제국의 정궁은 덕수궁과 경복궁이었으며, 중요한 행사는 경복궁에서 열렸지만 일반적으로 황실의 생활공간은 덕수궁으로 나누어 사용했다. 1896년 독립협회·만민공동회 등이 중심이 되어 청나라 등 외세의 간섭에서 벗어나고자 하는 자주독립운동을 활발하게 전개하자, 1897년 고종 황제가 연호를 ‘광무(光武)’로 정하고, 같은 해 10월 국명을 '대한제국(大韓帝國)'으로 고쳐 내외에 주권 국가임을 선포하였다. 이어 1899년에는 대한국 국제를 반포하여 자주독립국임을 재확인하는 동시에 황제권을 공고히 하였다. 대한제국 정부는 광무개혁을 위시로 한 여러 근대화 개혁을 시도했고, 새로운 근대적 자주국가로 거듭나기 위해..."
