    "yasaStory": "1908년 6월 30일 사건: 러시아 시베리아 포트카멘나야퉁구스카 강에서 거대한 폭발이 일어나다.\n\n러시아 연방(러시아어: Росси́йская Федера́ция 로시스카야 페데라치야[*], [rɐˈsʲiɪ̯skəɪ̯ə fʲɪdʲɪˈrat͡sɨɪ̯ə], 문화어: 로씨야련방), 약칭 러시아(러시아어: Росси́я 로시야[*], [rɐˈsʲiɪ̯ə], 문화어: 로씨야)는 동유럽과 북아시아에 걸쳐 있는 연방제 국가이다. 그 영토는 동유럽의 대부분과 북아시아 전역에 걸쳐 있으며, 11개의 시간대를 포함한다. 동쪽은 태평양과 알래스카, 서쪽은 노르웨이, 핀란드, 에스토니아, 라트비아, 리투아니아, 폴란드, 벨라루스와, 남쪽은 우크라이나, 조지아, 아제르바이잔, 카자흐스탄, 중화인민공화국, 몽골, 조선민주주의인민공화국과, 북쪽은 북극해와 접해 있으며 오호츠크해와 베링 해협, 알래스카주에서 미국, 일본과 해상 국경을 유지하고 있다. 러시아의 국가 면적은 17,098,246 km2으로 세계에서 면적이 가장 큰 국가이다. 러시아는 또한 유럽에서 인구가 가장 많고, 유라시아에서 여섯 번째로 많은..."
