    "sillokUrl": "https://ko.wikipedia.org/wiki/%EB%89%B4%EB%A9%95%EC%8B%9C%EC%BD%94%EC%A3%BC",
    "officialRecord": "뉴멕시코주 (1912년 1월 6일)와 애리조나주 (1912년 2월 14일)의 가입 이후 첫 독립기념일로, 이 날 미국 정부는 국기의 별 개수를 46개에서 48개로 늘리는 형태로 바꾸었다.",
    "yasaStory": "1912년 7월 4일 사건: 뉴멕시코주 (1912년 1월 6일)와 애리조나주 (1912년 2월 14일)의 가입 이후 첫 독립기념일로, 이 날 미국 정부는 국기의 별 개수를 46개에서 48개로 늘리는 형태로 바꾸었다.\n\n뉴멕시코주(영어: State of New Mexico, 스페인어: Estado de Nuevo México, 나바호어: Yootó Hahoodzo)는 미국 남서부의 주이다. 주를 상징하는 주기(州旗)는 스페인을 상징하는 노란색 바탕에 태양을 상징하는 지아(Zia) 인디언의 원형 무늬를 쓰고 있다. 주도는 1607년에 스페인인들이 건설한 도시인 샌타페이이다. 샌타페이는 미국에서 가장 역사가 긴 주도이며 두 번째로 역사가 긴 도시로 알려져 있다. 현재 뉴멕시코 주지사는 미쉘 루한 그리셤이다. 오랫동안 아메리카 원주민의 땅이었으며, 에스파냐의 총독령인 누에바에스파냐, 멕시코의 주 (이 당시에는 콜로라도주, 캔자스주, 오클라호마주, 텍사스주의 일부도 포함하는 큰 주로, 이름도 산타페데 누에보메히코 주였다.)를 거쳐 1848년에 끝난 멕시코-미국 전쟁의 결과로 미국의 영토가 되었다. 1912년 1월 미국의 47번째 주로 편입되었다(같은해 2월에 애리조나 주가 48번째로 편입). 2차대전 중 원자탄..."
