    "yasaStory": "1944년 7월 9일 사건: 조선인 징용자들이 승선한 타이헤이마루가 미국 잠수함 USS 선피시에 의해 격침되다.\n\n타이헤이마루 또는 다이헤이마루(일본어: 太平丸 たいへいまる[*] , 영어: Taihei Maru)는 일본 제국 해군이 제2차 세계 대전 및 태평양 전쟁에서 운용한 수송선이다. 1928년에 건조되었으며, 시마타니 키센(Shimatani Kisen), 다이도 카이운(Daido Kaiun)에 거쳐 일본 제국 해군이 운용하였다. 일본 해군은 타이헤이마루라는 수송선을 여러 대 운영하였으며, 약 8대 정도 보유하였다."
