    "yasaStory": "1921년 7월 11일 사건: 몽골이 중화민국으로부터 독립하다.\n\n몽골국(몽골어: Монгол Улс, ᠮᠣᠩᠭᠣᠯᠤᠯᠤᠰ 멍걸 올스 듣기 ), 약칭 몽골(몽골어: монгол 멍걸)은 동아시아의 내륙국이다. 면적은 1,564,116km2이며, 인구는 2024년 기준 약 350만 명이다. 북쪽으로 러시아, 남쪽으로 중화인민공화국에 접하여 있다. 수도는 울란바타르로, 몽골의 최대 도시이다."
