    "yasaStory": "1923년 6월 2일 사건: 국민대표대회가 결렬된 뒤 임시정부를 부정하는 김규식·이청천,신숙 등 창조파(創造派)가 모여 조선공화국 정부를 수립하다.\n\n국민대표회의는 1923년 중국 상하이 인민정부대례당에서 개최된 한국의 독립운동 계파간의 회의를 말한다. 이 회의에 모인 국내외 단체의 대표들은 대한민국 임시정부의 진로를 비롯한 독립운동 방안에 대해 논의하였다."
