    "title": "대한민국 임시정부의 기관지 〈독립신문〉을 발행하다.",
    "source": "위키백과 · 대한민국 임시정부",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EB%8C%80%ED%95%9C%EB%AF%BC%EA%B5%AD_%EC%9E%84%EC%8B%9C%EC%A0%95%EB%B6%80",
    "officialRecord": "대한민국 임시정부의 기관지 〈독립신문〉을 발행하다.",
    "yasaStory": "1921년 6월 9일 사건: 대한민국 임시정부의 기관지 〈독립신문〉을 발행하다.\n\n대한민국 임시정부(大韓民國臨時政府)는 1919년 발표된 3·1 독립선언서 및 3·1 운동에 기초하여 일본 제국의 대한제국 침탈과 식민 통치를 부인하고 한반도 내외의 항일 독립운동을 주도하기 위한 목적으로 설립된 망명정부이다. 간략히 임정정이라고 한다. 1919년 4월 11일 중화민국 상하이시에서 수립되었고, 1948년 8월 15일 대한민국 정부가 수립됨으로써 해산하였다. 1919년 3.1 운동 직후 대한국민의회, 상해 임시정부, 한성정부 등 각지에 임시정부가 수립된 뒤, 같은 해 9월 11일 한성정부의 법을 계승한다는 원칙하에 상하이를 거점으로 대한국민의회, 상해 임시정부, 한성정부 등 국내외 7개의 임시정부들이 개헌형식으로 통합되어 대한민국 임시정부로 개편되었다. 이때 4월 11일 제정된 대한민국 임시 헌장의 내용을 대폭 보강하여 9월 11일 대한민국 임시 헌법을 제정하여 국호는 '대한민국', 정치 체제는 '민주공화국'으로 하고, 대통령제를 도입하고, 입법·행정·사법의 3권 분리 제도를..."
