    "officialRecord": "체코슬로바키아의 리데체, 라인하르트 하이드리히의 암살에 대한 보복으로 파괴되다. 이 마을은 전후에 다시 재건되었다.",
    "yasaStory": "1942년 6월 9일 사건: 체코슬로바키아의 리데체, 라인하르트 하이드리히의 암살에 대한 보복으로 파괴되다. 이 마을은 전후에 다시 재건되었다.\n\n체코슬로바키아(체코어: Československo 체스코-슬로벤스코[*], 슬로바키아어: Česko-Slovensko 체스코-슬로벤스코, 문화어: 체스꼬슬로벤스꼬)는 1918년부터 1992년까지 (제2차 세계 대전 기간을 제외하고) 중앙유럽에 있었던 공화국이다. 1993년 1월 1일 체코와 슬로바키아로 나뉘었다. \"체코슬로바키아\"를 국명으로 사용한 정체는 총 다음과 같다. 체코슬로바키아 제1공화국: 1918년~1938년 체코슬로바키아 제2공화국: 1938년~1939년 체코슬로바키아 제3공화국: 1945년~1948년 체코슬로바키아 제4공화국: 1948년~1960년 체코슬로바키아 사회주의 공화국: 1960년~1990년 체코슬로바키아 연방공화국: 1990년~1992년"
