    "yasaStory": "1927년 6월 11일 사건: 한국의 독립운동: 평안남도의 독립운동단체 흑전사가 조직활동을 시작하였다.\n\n한국의 독립운동은 한국이 일제를 주축으로 한 제국주의 국가들의 침략 및 지배로부터 대항한 일련의 운동이다. 이러한 독립운동은 19세기 중엽부터 시작해 1945년 8월 15일에 일제가 항복을 선언할 때까지 진행되었다."
