    "yasaStory": "1943년 8월 1일 사건: 일본, 조선인에 대한 징병제 실시\n\n징용(徵用)은 전쟁, 사변 혹은 이에 준하는 비상사태가 발생한 때에 정상적으로 인력을 모집할 능력이 없는 국가에서 행정상, 혹은 군의 작전상 필요한 인적 자원을 강제적으로 집합시켜 착취하는 무자유 노동(강제노동)의 한 형태이다. 징용 제도는 일반적으로 인간의 기본적 인권과 자유의지에 반하여 이루어지며, 이를 거부하는 자는 법적으로 처벌되거나 사회적으로 제재당할 위협에 노출된다. 경우에 따라 약간의 보상을 지급하기는 하지만 징집과 노역 행위 자체는 강요된다. 넓은 의미에서의 징용은 종군 기자와 수행원들의 동원까지도 징용으로 보기도 한다. 징집에서 물건을 강제로 거두는 일을 징발(徵發), 군인을 모집하기 위한 것을 징병(徵兵)이라고 한다. 현재 대한민국은 세계에서 유일한 비전시상황의 징용국가다. 바로 공익근무가 징용이다. 징병이 불가능한 신체 정신적 조건자까지 공익근무로 최저임금에도 미치지 못하는 열악한 급여로 본인이 원하지 않는 공무원의 하인 수준의 보조업무에서부터 3D업종 근무까지 강요하며..."
