    "yasaStory": "1923년 9월 1일 사건: 간토 대지진: 일본의 간토 지방에서 지진이 발생하다. 지진 직후의 혼란 속에서 재일 조선인 6천 명이 군경과 자경단이 휘두른 죽창 등에 살해되다.\n\n간토 대지진(일본어: 関東大地震 간토다이지신[*]) 또는 한국에서는 관동 대지진은 1923년 9월 1일(다이쇼 12년) 11시 58분(일본 표준시)에 일본 도쿄도 등을 포함한 미나미칸토 지역을 중심으로 일어난 해구형 지진이다. 지진의 진동은 본진이 시작될 때부터 완전히 멈출 때까지 4분에서 최대 10분까지 걸린 오래 지속된 지진이다. 이 지진으로 인한 직접적인 피해 및 조선인을 대상으로 한 무차별적인 간토 대학살 등을 통틀어 간토 대진재(일본어: 関東大震災 かんとうだいしんさい[*])라고 부른다. 1703년(겐로쿠 16년)에 일어난 지진도 간토 대지진과 거의 비슷한 구조로 일어났기 때문에 일본에서는 이 지진을 다이쇼 간토 지진(일본어: 大正関東地震)으로 부르고 1703년 간토 지진을 겐로쿠 간토 지진으로 부르는 경우도 있다. 이 두 지진은 사가미 해곡의 판 경계를 따라 일어난 것으로 추정되기 때문에 두 지진을 한데 묶어 사가미 해곡 거대지진으로 부르며 간단하게 사가미 해곡에서 일어나는..."
