    "yasaStory": "1945년 8월 17일 사건: 인도네시아가 독립을 선언하다.\n\n인도네시아 공화국(인도네시아어: Republik Indonesia 레푸블릭 인도네시아[*], 영어: Republic of Indonesia), 약칭 인도네시아(인도네시아어: Indonesia)는 동남아시아에서 오세아니아까지 이어진 섬나라이다. 17,000개 이상의 섬이 있으며 주요 섬들은 수마트라, 자와(자바), 보르네오, 술라웨시, 뉴기니 등이다. 인도네시아의 면적은 1,904,569km2로 세계에서 14번째로 면적이 넓은 나라이며, 세계에서 가장 면적이 넓은 섬나라이다. 인구는 약 2억 8천만 명으로 세계에서 4번째로 인구가 많은 나라이며, 세계 섬나라 중에서 인구가 가장 많은 섬나라이다. 세계에서 가장 인구가 밀집된 섬인 자와섬에는 인도네시아 전체 인구의 절반 이상이 모여 산다. 특히 발리섬과 수도 자카르타는 여행객이 많다. 인도네시아는 대통령제를 채택했으며, 선거로 선출한 의회가 입법부를 구성하는 입헌 공화국이다. 38개의 지방들 중 5개가 특별 지위 지역이다. 인도네시아 수도인..."
