    "yasaStory": "1911년 8월 23일 사건: 일본, 조선교육령 공포.\n\n대일본제국(일본어: 大日本帝国 다이닛폰테이코쿠[*], 일본어 구자체: 大日本帝󠄁國), 통칭 일본 제국(일본어: 日本帝国 닛폰테이코쿠[*]), 줄여서 일본(일본어: 日本 닛폰[*]) 혹은 일제(한국 한자: 日帝󠄁)는 1868년의 메이지 유신으로 일본에 성립되어 1947년 일본국 헌법이 시행될 때까지 일본 열도, 한반도, 타이완섬, 사할린 등지에 존속했던 국가이다. 일본 제국은 ‘부국강병’과 ‘식산흥업’의 기치를 내걸고 아시아에서 가장 빠른 속도의 산업화와 군사화를 거쳤다. 일본은 메이지 유신 이래 빠른 속도로 탈바꿈하며 강대국으로 떠올랐고, 청일 전쟁, 의화단의 난, 러일 전쟁, 제1차 세계대전 이후에는 중국을 제치고 거대한 식민 제국을 경영하였다. 허나 1920년대에 대공황의 바람이 몰아닥치자 일본 내부에서도 군국주의, 민족주의, 전체주의의 광풍이 강해지기 시작하였다. 이후 제2차 세계대전에서 일본은 추축국에 가담하였고, 중국과 동남아시아의 광대한 영토를 식민지화하며 위안부 강제동원..."
