    "title": "이승만, 미국 워싱턴 D.C.에 임시정부 구미위원회 설립.",
    "source": "위키백과 · 이승만",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%9D%B4%EC%8A%B9%EB%A7%8C",
    "officialRecord": "이승만, 미국 워싱턴 D.C.에 임시정부 구미위원회 설립.",
    "yasaStory": "1919년 8월 25일 사건: 이승만, 미국 워싱턴 D.C.에 임시정부 구미위원회 설립.\n\n이승만(李承晚, 1875년 3월 26일 ~ 1965년 7월 19일)은 일제강점기 한국의 독립운동가이자 대한제국과 대한민국의 정치인이다. 대한민국 임시정부의 초대 대통령이자 대한민국의 제 1~3대 대통령이다. 본관은 전주로 왕실 후손이며 1949년 건국훈장 대한민국장에 서훈되었다. 아명은 승룡(承龍), 호는 우남(雩南)이다. 이승만 대통령은 황해도 평산군에서 태어났다. 대한제국 시절 고종황제가 설립한 《독립신문》과 《협성회회보》 주필, 독립협회 활동 등 계몽운동을 하였고, 왕정 폐지와 공화국 수립을 도모하였다는 반역의 죄목으로 한성감옥에 투옥됐다. 수감 시절 개신교로 개종하고, 옥중에서 계몽활동을 하고, 《독립정신》을 저술하였다. 대한제국 말기 헐버트의 상서로 고종황제가 특별히 사면하였다. 고종은 황실내탕금을 지원하여 밀사로 도미시켜 조미수호조약의 유효성을 확인하라는 특명을 내렸으나 큰 성과를 거두지 못하고, 미국에서 학업을 계속하여 5년에 걸쳐 조지워싱턴 대학교에서 학사, 하버드..."
