    "yasaStory": "1945년 8월 28일 사건: 호찌민, 베트남 공화국 임시정부 수립.\n\n호찌민(베트남어: Hồ Chí Minh 듣기 ), 1890년 5월 19일~1969년 9월 2일)은 베트남의 공산주의 혁명가이자 독립운동가, 정치인, 초대 국가주석이다. 원래 이름은 응우옌신꿍(베트남어: Nguyễn Sinh Cung). 베트남 사람들에게는 호 할아버지(베트남어: Bác Hồ)라는 이름으로 불리고 있다. 생전에 가명과 필명이 모두 약 50~200여 개 이상 되었다. 호찌민은 판보이쩌우 이후 베트남 독립운동의 주요 인물로 일생을 베트남의 독립을 위해 바쳤으며, 베트남 공산당, 베트남 독립연맹 등을 창건하였고, 1945년 베트남 민주 공화국을 선포하고 정부 수상(1946-1955), 국가주석(1945~1969)과 베트남 노동당 주석(1951~1969)을 지냈다. 호찌민은 1911년 대 초 사이공에서 프랑스 선적의 배에 선원으로 취직하여 미국을 거쳐 프랑스로 가 유학하던 중 프랑스 공산당에 입당하였다. 1930년에는 중국에서 베트남 공산당(현 베트남 노동당의 전신)을 창건하여..."
