    "officialRecord": "한일 병합 조약이 공포됨으로써 대한제국이 완전히 멸망되고 일본에 지배를 당하게 되었다. (경술국치)",
    "yasaStory": "1910년 8월 29일 사건: 한일 병합 조약이 공포됨으로써 대한제국이 완전히 멸망되고 일본에 지배를 당하게 되었다. (경술국치)\n\n한일병합조약(한국 한자: 韓日倂合條約) 또는 한국 병합에 관한 조약(일본어: 韓国併合に関する条約 간코쿠 헤이고니 간스루 조야쿠[*])은 1910년 8월 22일에 조인되어 8월 29일 발효된 일본 제국과 친일파 사이에 이루어진 합병조약이다. 한일합방조약(한국 한자: 韓日合邦条約)이라고도 불린다. 친일파 이완용과 제3대 한국 통감인 데라우치 마사타케가 불법적인 회의를 거쳐 조약을 통과시켰으며, 조약의 공포는 8월 29일에 이루어져 이날 일본 제국 천황이 한국의 국호를 고쳐 조선이라 칭하는 건과 한국 병합에 관한 조서를 공포함으로써 대한제국은 일본 제국의 식민지가 되었다. 한국에서는 경술국치(한국 한자: 庚戌國恥), 국권피탈(한국 한자: 國權被奪), 등으로 호칭하기도 한다. 을사늑약으로 외교권을 일본에 양도하고 일본의 보호국이 되었고, 정미7조약으로 군대 해산을 당하고, 기유각서로 사법권과 감옥사무까지 잃은 대한제국은 결국 멸망했고, 일제강점기가 시작되었다. 한편 병합조약 직후 황현, 한규설..."
