    "officialRecord": "이동휘, 대한민국 임시정부 국무총리에 취임.",
    "yasaStory": "1919년 8월 30일 사건: 이동휘, 대한민국 임시정부 국무총리에 취임.\n\n이동휘(李東輝, 1873년 6월 20일~1935년 1월 31일)는 대한제국 시대의 군인 겸 정치인이고, 일제강점기 시대와 대한민국 임시정부 시대의 사회주의 계열 독립운동가로 활약한 정치인이다. 대한제국 육군 장교 출신으로, 특히 한말 애국계몽운동기에는 의병 운동을 이끌었고 함경도, 평안도, 북간도, 연해주 한인 사회 등에서 활동하면서 기독교인으로 기독교 사상을 전파하는 독실한 전도사로 활동하기도 했다. 1919년 대한민국임시정부의 국무총리를 역임하기도 했다. 아호(雅號)는 성재(誠齋)이며 대자유(大自由)라는 호(號)를 사용하기도 했다."
