    "yasaStory": "1910년 9월 30일 사건: 일본, 조선 토지 조사 사업 착수\n\n일본국, 약칭 일본은 동아시아에 있는 섬나라로, 네 개의 주요 섬(홋카이도, 혼슈, 시코쿠, 규슈)과 수천 개의 부속도서들로 구성되어 있다. 일본의 전체 면적은 37만 7,973km2로, 독일(35만 7,386km2)보다 조금 더 넓으며, 인구는 1억 2,380만 명(거주등록외국인 350만6천명 포함)으로 세계에서 11번째로 많다. 도쿄를 중심으로 한 수도권을 이루는 간토 지방은 세계에서 가장 큰 대도시권이며, 이 지역에만 4,354만 명(일본 전체 인구의 35%)이 거주하고 있다. 현재의 일본은 1945년 포츠담 선언 서명 이후 1947년에 제정·시행된 일본국 헌법에 의해 법적으로 성립한 국가이다. 일본국 헌법이 제정되고 일본은 입헌군주제를 채택하고 있으며 상징적인 국가원수 역할을 하는 천황과 국민의 선거를 통해 선출되는 참의원(상원)·중의원(하원)으로 구성되는 국회가 공존하고 있다. 현재의 천황은 나루히토, 내각총리대신은 자유민주당 소속의 다카이치 사나에이다. 경제력은 2024년..."
