    "yasaStory": "1920년 10월 2일 사건: 훈춘 사건: 중화민국 지린성 옌볜 훈춘에서 마적단의 습격을 핑계로 일본 제국군이 조선인을 학살\n\n훈춘 사건(琿春事件)은 1920년 10월 2일 만주에 있는 일본 영사관에 대한 습격으로 보고된 사건이다. 이 사건으로 13명의 일본인이 사망했다고 한다. 일본 정부는 이 사건을 구실로 1920년 10월 5일 수천 명의 일본 제국 육군 병력을 만주로 파견했다. 이러한 확전은 일본과 대한독립군 사이의 청산리 전투 (1920년 10월 21일~26일)로 이어졌으며, 이 전투에서 한국 독립군이 일본군과 싸웠다."
