    "sillokUrl": "https://ko.wikipedia.org/wiki/%EA%B9%80%EC%9B%90%EB%B4%89",
    "officialRecord": "김원봉, 중국 한커우에서 조선의용대 창설.",
    "yasaStory": "1938년 10월 10일 사건: 김원봉, 중국 한커우에서 조선의용대 창설.\n\n김원봉(金元鳳, 1898년 9월 28일~1958년 11월)은 한국의 독립운동가, 정치인이다. 일제강점기의 의열단장을 역임했다. 호는 약산(若山), 본관은 김해(金海)이다. 경남 밀양에 의열 기념관이 있다. 1919년 아나키즘 단체인 의열단(義烈團)을 조직하였고, 황푸 군관학교를 거쳐 조선의용대를 조직하였다. 대한민국 임시정부에 합류하여 임시의정원(경상도 지역구)의원, 한국 광복군 부사령관 겸 제1지대장으로 활동하였고, 1944년 임시정부 군무부장에 선출됐다. 1946년 2월 민족주의민주전선 공동의장, 6월 인민공화당 위원장을 역임하였다. 1948년 김구·김규식 등과 함께 남북협상에 참여한 뒤에 그대로 북한에 남았다. 조선민주주의인민공화국 정부수립 후 국가검열상, 조선인민공화당 중앙위원회 위원장, 노동상, 최고인민회의 상임위원회 부위원장을 역임했다. 한국전쟁이 발발하자 군사위원회 평안북도 전권대표로서 후방에서 조선인민군의 군량미를 생산하는 일을 했다. 이로 인해 김일성으로부터 로력훈장을..."
