    "officialRecord": "김일성, 조선 공산당 북조선 분국 설치(46년 7월 북조선노동당으로 개편한 뒤 49년 6월 남조선노동당을 흡수해 조선노동당으로 확대)",
    "yasaStory": "1945년 10월 10일 사건: 김일성, 조선 공산당 북조선 분국 설치(46년 7월 북조선노동당으로 개편한 뒤 49년 6월 남조선노동당을 흡수해 조선노동당으로 확대)\n\n김일성(金日成, 1912년 4월 15일~1994년 7월 8일)은 조선민주주의인민공화국의 초대 최고 지도자이다. 1912년 평양의 개신교 가정에서 태어나, 어린 시절 아버지를 따라 만주로 이주했다. 일제강점기 때 중국공산당의 당원으로서 동북항일연군에서 복무했고, 이후 소련군 제88독립보병여단에서 복무하였다. 해방 후 조선공산당 북조선분국, 북조선공산당, 북조선로동당에서 고위직을 맡으며 북조선에 진주한 소비에트 연방군의 대리자로 활동하였고, 남북조선의 로동당 통합 이후 조선로동당의 위원장이 되었다. 1948년 8월 최고인민회의를 구성하고, 9월 9일 내각 총리가 되었다. 소련의 이오시프 스탈린과 중화인민공화국의 마오쩌둥을 설득해 승인을 받아 1950년 6월 25일 새벽 4시 6.25 전쟁을 일으켰고 조선인민군 최고사령관으로 인민군을 지휘했으나 한국군과 유엔군이 반격하자 중국인민지원군과 소련군의 도움을 받아 약 3년 간 전쟁을 계속했다. 1953년 7월 27일 22시 휴전협정이 맺어진 이래..."
