    "officialRecord": "데라우치 마사타케가 조선총독직에서 물러났다.",
    "yasaStory": "1916년 10월 14일 사건: 데라우치 마사타케가 조선총독직에서 물러났다.\n\n데라우치 마사타케(일본어: 寺内正毅, 가에이 5년(1852년) 2월 24일 ~ 다이쇼 8년(1919년) 11월 3일)는 일본 제국의 육군 군인, 정치인, 외교관으로 작위는 백작이다. 제18대 내각총리대신을 지냈다. 1910년 5월부터는 제3대 한국통감이었고, 한일합병 이후부터 1916년 10월 14일까지 초대 조선총독이었다. 호는 오보(桜圃) 또는 로안(魯庵)이다. 빌리켄 재상(Billiken 宰相)이라고도 불렸다. 메이지 유신 시대에 군인으로 임관한 뒤 보신 전쟁과 세이난 전쟁에 출정하였다. 1882년 프랑스 주재무관이 되고, 일본 육군사관학교 교장을 거쳐 1898년 일본 육군교육 총감을 지냈다. 1900년대 초에는 남만주 철도 설립위원장을 맡았다. 1902년 3월 국방부 육군담당 대신이 되었으며, 러일 전쟁에 참전한 공로로 자작이 되고 육군 대장까지 승진했다. 1910년 5월 제3대 한국통감으로 부임하여 한일합병을 성사시키고 초대 조선총독이 되었다. 1916년 총리대신이 되어 시베리아..."
