    "yasaStory": "1940년 10월 15일 사건: 아돌프 히틀러를 소재로 한 찰리 채플린 감독·주연의 영화 《위대한 독재자》가 개봉되다.\n\n아돌프 히틀러(독일어: Adolf Hitler, 1889년 4월 20일~1945년 4월 30일)는 오스트리아 태생의 독일 정치인으로, 1933년부터 1945년 자살할 때까지 나치 독일의 독재자였다. 나치당을 이끌고 권력을 장악하여 1933년 총리가 된 이후 1934년 퓌러로 취임했다. 1939년 9월 1일 폴란드 침공을 통해 제2차 세계 대전을 일으킨 히틀러는 전쟁 내내 군사 작전에 긴밀히 관여했으며, 600만 명의 유대인과 다른 희생자들에 대한 집단학살인 홀로코스트를 자행하는 데 주도적인 역할을 했다. 히틀러는 오스트리아-헝가리 브라우나우암인에서 태어나 린츠 근방에서 성장했고, 1900년대 초반 빈에 살다가 1913년 독일로 이주했다. 제1차 세계 대전 도중 독일군에 복무하여 철십자 훈장을 받았다. 1919년 나치당의 전신인 독일 노동자당(DAP)에 가입했고, 1921년 이름이 바뀐 나치당의 당대표로 임명되었다. 그는 1923년 뮌헨 폭동으로 정부 권력을 탈취하려고 시도했지만, 실패하여..."
