    "yasaStory": "1905년 10월 26일 사건: 노르웨이가 스웨덴에서 독립.\n\n노르웨이 왕국(보크몰: Kongeriket Norge 콩에리케 노르게[*], 뉘노르스크: Kongeriket Noreg 콩에리케 노레그[*]), 약칭 노르웨이(보크몰: Norge 노르게[*], )는 북유럽 스칸디나비아 나라이다. 수도는 오슬로이며, 공용어는 노르웨이어이다. 주력 산업은 어업, 석유 산업 및 서비스업이며 전세계에서 민주주의 지수가 가장 높으며 취약국가지수에서 최하위에 머물러 있는 청렴 선진국이기도 하다. 노르웨이는 북이라는 뜻의 nor, 길이라는 뜻의 way가 합쳐진 말로, 북극으로 가는 길이라는 뜻이 있다. 스칸디나비아반도의 서쪽 부분, 얀마옌섬, 스발바르 제도, 그리고 부베섬으로 이루어져 있다. 면적은 385,207 km2이며 인구는 약 490만 명 정도이다. 유럽에서 두 번째로 인구 밀도가 작은 나라다. 나라의 대부분이 동쪽의 스웨덴과 국경을 맞대고 있고, 노르웨이의 북쪽 지역은 남쪽은 핀란드, 동쪽은 러시아와 국경을 접하고 있다. 남쪽의 스카게라크 해협의 건너편에는..."
