    "yasaStory": "1917년 12월 6일 사건: 핀란드가 러시아로부터 독립을 선언하다.\n\n핀란드 공화국(핀란드어: Suomen tasavalta 수오멘 타사발타[*]), 약칭 핀란드(핀란드어: Suomi 수오미[*] [ˈsuo̯mi] 듣기 )는 북유럽에 있는 노르딕 국가 가운데 하나이다. 발트해, 보트니아만, 핀란드만을 두고서 서쪽으로는 스웨덴, 북쪽으로는 노르웨이, 동쪽으로는 러시아, 남쪽으로는 핀란드만을 두고 에스토니아와 접하고 있다. 핀란드 수도인 헬싱키는 핀란드에서 가장 큰 도시이다. 다른 핀란드 주요 도시로는 에스포, 탐페레, 오울루, 투르쿠, 이위배스퀼래, 라흐티, 쿠오피오 등이 있다. 인구는 2022년 9월 기준 555만 9198명이며, 핀란드 중앙과 남부에 사는 인구 대부분이 핀란드어를 사용한다. 핀란드어는 북게르만어군과 관계 없는 우랄어족의 핀어군에 속한다. 핀란드 전체 인구 가운데 140만 명이 헬싱키 수도권에 살고 있으며, 이 지역은 핀란드 전체 GDP의 30% 이상을 생산한다. 핀란드 공식 언어 가운데 두 번째로 많이 사용한 언어는 스웨덴어로 올란드..."
