    "yasaStory": "1931년 11월 7일 사건: 강서성 서금에서 중화소비에트공화국 임시정부 수립. 주석 마오쩌둥 옹립.\n\n장시성(중국어: 江西省, 병음: Jiāngxī Shěng) 또는 강서성은 중화인민공화국 중남부에 있는 성이다. 장강 남쪽에 있으며 성도는 난창이다."
