    "yasaStory": "1921년 11월 14일 사건: 대한민국 최초의 영화 월하의 맹서 제작.\n\n《월하의 맹서》(月下의 盟誓)는 조선 총독부에서 자금을 댄 목적성 영화이며, 1923년 처음 상영되었다. 흑백 35밀리로 촬영된 무성 영화이다. 《월하의 맹서》는 윤백남이 첫 번째 각본, 감독한 작품으로 민중극단 단원들이 대거 출연하였다. 이때 윤백남은 민중극단 단원이었던 이월화를 여주인공으로 발탁하였다."
